      "Wanderer away from Jesus, Would'st thou not a crown obtain? Why then wilt thou slight His goodness? Fearest not the woe and pain? Can you barter life eternal, For the pleasure sin can give! Turn, oh, turn you to the Savior, And a fadeless crown receive."
