      "Did you hear the loving word? Pass it on, pass it on! Like the singing of a bird? Pass it on, pass it on! Let its music live and grow, Let it cheer another’s woe; You have reaped what others sow, Pass it on, pass it on!",
      "Have you found the heav’nly light? Pass it on, pass it on! Souls are groping in the night, Daylight gone, daylight gone! Hold your lighted lamp on high, Be a star in someone’s sky, He may live who else would die, Pass it on, pass it on!"
