      "How far, how far to the City of God? The saddened hearts would know, While mourning o'er the friends they love, In death's embrace laid low; How long ere saints awake And pass those portals fair? Hope whispers in affliction's hour, Weep not, they're almost there.",
      "How far, how far to the City of Gold? Where sorrow ne'er shall come The promised land of joy and rest, The saints' eternal home? The journey long has been, But home will soon appear; Each landmark past proclaims to us We're almost, almost there."
