      "In mansions of glory and endless delight, I'll ever adore thee in heaven so bright; I'll sing with the glittering crown on my brow: If ever I loved thee, my Jesus, 'tis now. Psalter Hymnal, (Gray) ## Author (attributed to): James H. Duffell Born in West Bromwich, England; worked as an iron smelter; was married with three children; emigrated to Sydney, Australia, in 1881 and died there. Go to person page > ## Author (attributed to): William R. Featherston William Ralph Featherston(e) Canada 1846-1873. Born at Montreal, Quebec, Canada, he joined the Wesleyan Methodist Church there. He became a Christian at age 16 while in Toronto, and is thought to have written his famous hymn about the same time. He sent the poem to his aunt, Ms. E. Featherston Wilson and she gave it to a publisher. Adoniram. J Gordon, an evangelist, founder of Gordon College & Gordon-Conwell Theological Seminary, found the hymn in a 1870 London hymnal and was impressed with the words, but did not like the tune, so he composed the melody that has been used with the hymn ever since. Featherstone is thought to have married Julie R MacAlister in 1869 and that they had a son, John, in 1870. Featherstone died in Montreal a… Go to person page >"
