      "Think of His goodness, and patience and love; Mercy is free, Mercy is free: Pleading thy cause with His Father above, Mercy is boundless and free. Come, and repenting, O give Him thy heart! Mercy is free, mercy is free: Grieve Him no longer, but come as thou art, Mercy is boundless and free.",
