    "verses_en": [
      "Savior, like a shepherd lead us, Much we need Thy tender care; In Thy pleasant pastures feed us, For our use Thy folds prepare: Blessèd Jesus, blessèd Jesus, Thou hast bought us, Thine we are; Blessèd Jesus, blessèd Jesus, Thou hast bought us, Thine we are.",
      "We are Thine, do Thou befriend us, Be the guardian of our way; Keep Thy flock, from sin defend us, Seek us when we go astray: Blessèd Jesus, blessèd Jesus, Hear, O hear us when we pray; Blessèd Jesus, blessèd Jesus, Hear, O hear us when we pray.",
      "Thou hast promised to receive us, Poor and sinful though we be; Thou hast mercy to relieve us, Grace to cleanse, and pow'r to free: Blessèd Jesus, blessèd Jesus, Early let us turn to Thee; Blessèd Jesus, blessèd Jesus, Early let us turn to Thee.",
      "Early let us seek Thy favor, Early let us do Thy will; Blessed Lord and only Savior, With Thy love our bosoms fill: Blessèd Jesus, blessèd Jesus, Thou hast loved us, love us still; Blessèd Jesus, blessèd Jesus, Thou hast loved us, love us still. Hymns for the Living Church ## Author (attributed to): Dorothy A. Thrupp Dorothy Ann Thrupp was born in London, June 10, 1779. She contributed some hymns, under the pseudonym of \"Iota,\" to W. Carus Wilson's Friendly Visitor and his Children's Friend. Other hymns by her, signed \"D.A.T.,\" appeared in Mrs. Herbert Mayo's Selection of Hymns and Poetry for the Use of Infant Schools and Nurseries, 1838. She was also the editor of Hymns for the Young, c. 1830, in which all the hymns were given anonymously. She died in London on December 15, 1847. --The Hymnal 1940 Companion… Go to person page > ## Author (attributed to): Henry F. Lyte Lyte, Henry Francis, M.A., son of Captain Thomas Lyte, was born at Ednam, near Kelso, June 1, 1793, and educated at Portora (the Royal School of Enniskillen), and at Trinity College, Dublin, of which he was a Scholar, and where he graduated in 1814. During his University course he distinguished himself by gaining the English prize poem on three occasions. At one time he had intended studying Medicine; but this he abandoned for Theology, and took Holy Orders in 1815, his first curacy being in the neighbourhood of Wexford. In 1817, he removed to Marazion, in Cornwall. There, in 1818, he underwent a great spiritual change, which shaped and influenced the whole of his after life, the immediate cause being the illness and death of a brother cler… Go to person page >"
    ],
