      "Wonderful story of love! Though you are far away; Wonderful story of love! Still he doth call today. Calling from Calvary’s mountain, Down from the crystal bright fountain, E’en from the dawn of creation; Wonderful story of love!",
      "Wonderful story of love! Jesus provides a rest; Wonderful story of love! For all the pure and blest; Rest in those mansions above us, With those who’ve gone on before us, Singing the rapturous chorus; Wonderful story of love!"
