    "first_line_yoruba": "",
    "category": "Praise",
    "verses_en": [
      "O sweet will of God! thou hast girded me ’round, Like the deep, moving currents that girdle the sea; With omnipotent love is my poor nature bound, And this bondage to love sets me perfectly free.",
      "For years my soul wrestled with vague discontent That like a sad angel o’ershadowed my way; God’s light in my soul with the darkness was blent, And my heart ever longed for an unclouded day.",
      "And now I have flung myself recklessly out, Like a chip on the stream of the Infinite Will; I pass the rough rocks with a smile and a shout, And I just let my God His dear purpose fulfill.",
      "Forever I choose the good will of my God, Its holy, deep riches to love and to know; The serfdom of love to so sweeten the rod, That its touch maketh rivers of honey to flow.",
      "Roll on, checkered seasons, bring smiles or bring tears, My soul sweetly sails on an infinite tide; I shall soon touch the shores of eternity’s years, And near the white throne of my Savior abide."
    ],
