    "first_line_yoruba": "",
    "category": "Prayer",
    "verses_en": [
      "Hark! I hear my Savior say: \"Suffer the children to come to Me\"; Do not turn the lambs away, \"Suffer the children to come.\" Point them to the Father’s throne, Speak to them in tenderest tone, Jesus calls them for His own, \"Suffer the children to come.\"",
      "Tell them Jesus loves them all, \"Suffer the children to come to Me\"; Take them gently by the hand, \"Suffer the children to come.\" Oh, forbid them not, I pray, Let the children come today, Hear the blessèd Savior say: \"Suffer the children to come.\"",
      "Take them gently by the hand, \"Suffer the children to come to Me\"; Lead them to the better land, \"Suffer the children to come.\" Lead them with a willing mind, Tell them of a Savior kind; They eternal life may find, \"Suffer the children to come.\""
    ],
