      "When the voice shall cry, Go ye forth tonight, Behold, the Bridegroom comes! Then the pulse will cease, and the heart grow still, And the eyes will close, and the blood grow chill, And the soul will take its eternal flight, For lo, the Bridegroom comes!",
      "Brother, trim your lamp, have it burning bright, Behold, the Bridegroom comes! He will surely come, though He seemeth late, Be at peace with Him, nor a moment wait, You will hear the cry ere the morning light, Behold, the Bridegroom comes!",
      "Hast thou made a vow? hasten ye to pay, Behold, the Bridegroom comes! For when He has come, and hath closed the door, And ye stand and pray, Open, we implore, It will be too late—pay your vows today, Behold, the Bridegroom comes!"
