    "first_line_en": "The mercy of God is an ocean divine",
    "first_line_yoruba": "",
    "category": "Evangelism",
    "verses_en": [
      "The mercy of God is an ocean divine, A boundless and fathomless flood; Launch out in the deep, cut away the shore line, And be lost in the fullness of God.",
      "But many, alas! only stand on the shore And gaze on the ocean so wide; They never have ventured its depths to explore, Or to launch on the fathomless tide.",
      "And others just venture away from the land, And linger so near to the shore, That the surf and the slime that beat over the strand, Dash o'er them in floods evermore.",
      "O let us launch out on this ocean so broad, Where the floods of salvation e’er flow; O, let us be lost in the mercy of God, Till the depths of His fullness we know."
    ],
