    "hymn_number": 176,
    "title_en": "Who can it be?",
    "title_yoruba": "",
    "first_line_en": "I've wandered in sorrow and sin",
    "first_line_yoruba": "",
    "category": "Praise",
    "verses_en": [
      "I've wandered in sorrow and sin, My heart it was heavy and sore, I heard a voice saying, \"Arise and come in, And Wander in sorrow no more. Who can it be? Who can it be? Thus I was wondering, Who can it be, Tenderly calling to me?",
      "I've struggled in doubt and in fear, Not knowing to whom I should go, I heard a voice saying, \"Son, be of good cheer,\" So soothingly tender and low. Who can it be? Who can it be? Thus I was wondering, Who can it be, Tenderly calling to me?",
      "I've heard it again and again, Wherever my footsteps did roam, It melted my heart with its pitying strain, It lighted my soul of its gloom. Oh, it was Thee! Oh, it was Thee! Savior of men, O my Jesus, 'twas Thee! Tenderly calling to me?",
      "I turned to my Father above, I read of his promises sure, I thought of my Savior, His cross and His love, And, oh! what a Friend I found there! Oh, what a Friend! Oh, what a Friend! Savior from sin thou hast been unto me, Savior of sin unto me.",
      "I'm groping in darkness no more, His glory illumines my way; I'm walking by faith, and His promises are My solace and joy ev'ry day. Yes, ev'ry day! Yes, ev'ry day! Jesus of Nazareth lighteth my way, Jesus now lighteth my way."
    ],
