      "Over the rolling sea, Millions are perishing, Lord, without Thee; We are blessed with Gospel light, While they grope in heathen night, And we send not, O the shame! Help to them in the Savior’s dear name, Over the rolling sea, Over the rolling sea!",
      "Over the rolling sea, There is a mission of mercy for me; Souls by years of sin depraved By my efforts may be saved, If I help to send the light To the people now shadowed in night Over the rolling sea, Over the rolling sea!"
