      "Must I go on in sin and sorrow, Today in sunshine, clouds tomorrow? First I'm sinning, then repenting, Now I'm stubborn, then relenting.",
      "With anguish wrung, I cried, \"My Lord, Is there not pow'r in Jesus' blood To make in me a perfect cure, To cleanse my heart and keep it pure?\"",
      "\"Oh, yes, the blood applied within Will cleanse your heart from ev'ry sin, And wash away your guilty stains, And cleanse till not one spot remains.\""
