    "first_line_en": "Holy Spirit, faithful Guide",
    "first_line_yoruba": "",
    "category": "Prayer",
    "verses_en": [
      "Holy Spirit, faithful Guide, Ever near the Christian’s side, Gently lead us by the hand, Pilgrims in a desert land; Weary souls fore’er rejoice, While they hear that sweetest voice, Whispering softly, “Wanderer, come! Follow Me, I’ll guide thee home.”",
      "Ever present, truest Friend, Ever near Thine aid to lend, Leave us not to doubt and fear, Groping on in darkness drear. When the storms are raging sore, Hearts grow faint, and hopes give o’er– Whisper softly, “Wanderer, come! Follow Me, I’ll guide thee home.”",
      "When our days of toil shall cease, Waiting still for sweet release, Nothing left but heaven and prayer, Wondering if our names are there; Wading deep the dismal flood, Pleading naught but Jesus’ blood, Whisper softly, “Wanderer, come! Follow Me, I’ll guide thee home.” AMEN."
    ],
