      "Five bleeding wounds he bears, Received on Calvary; They pour effectual prayers, They strongly speak for me; Forgive him, oh forgive, they cry, Nor let that ransomed sinner die.",
      "The Father hears him pray, His dear Anointed One; He cannot turn away The presence of his Son; His Spirit answers to the blood And tells me I am born of God.",
      "My God is reconciled, His pard’ning voice I hear; He owns me for his child; I can no longer fear; With confidence I now draw nigh, And Father, Abba Father, cry!"
